tools.exec_command({cmd:"rtk read AGENTS.md","max_output_tokens":6000}),
tools.exec_command({cmd:"rtk read /Users/gabe/.codex/RTK.md","max_output_tokens":6000}),
tools.exec_command({cmd:"rtk read /Users/gabe/.codex/plugins/cache/wisp-plugins/smith/2.4.2/skills/implement/SKILL.md","max_output_tokens":12000}),
tools.exec_command({cmd:"rtk git status --short","max_output_tokens":4000})
]); for(let i=0;i<results.length;i++) text({i,...results[i]});
